using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Xml;using System.Windows.Forms;using BeamScheduleFormatter;
class EarthworkFootingTests {
 static int checks;static void Check(bool v,string m){checks++;if(!v)throw new Exception(m);}static void Near(double a,double b,string m){Check(Math.Abs(a-b)<1e-7,m+": "+a+" != "+b);}static void Reject(Action a,string m){bool rejected=false;try{a();}catch{rejected=true;}Check(rejected,m);}static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,args);}
 static FootingBarSpec[] Bars(){return new[]{new FootingBarSpec{Diameter=16,Spacing=150},new FootingBarSpec{Diameter=12,Count=8},new FootingBarSpec(),new FootingBarSpec()};}
 [STAThread]static void Main(){
  Near(QuantityMath.Station("1+025.50"),1025.5,"Chainage");Near(QuantityMath.Station("25"),25,"Metre station");Reject(()=>QuantityMath.Station("0+1000"),"Invalid offset");Reject(()=>QuantityMath.Station("-1"),"Negative chainage");
  var cut=new CutFillInterval{Alignment="A",Start=0,End=20,CutStart=2,CutEnd=4,FillStart=1,FillEnd=2};cut.Validate();Near(cut.Cut,60,"Cut end areas");Near(cut.Fill,30,"Fill end areas");var next=new CutFillInterval{Alignment="A",Start=20,End=40};CutFillInterval.CheckOverlap(new[]{cut,next});checks++;next.Start=19;Reject(()=>CutFillInterval.CheckOverlap(new[]{cut,next}),"Overlapping intervals");next.Alignment="B";CutFillInterval.CheckOverlap(new[]{cut,next});checks++;
  var soil=new EarthworkMaterial{Bank=100,Fill=0};var demand=new EarthworkMaterial{Bank=0,Fill=80};var b=EarthworkBalance.Calculate(new[]{soil,demand});Near(b.LooseCommonBorrow,0,"Transfer surplus between entries before buying");Near(b.LooseFromExcavation,80/0.9*1.2,"Loose material used");Near(b.LooseSurplus,120-b.LooseFromExcavation,"Loose surplus");var reversed=EarthworkBalance.Calculate(new[]{demand,soil});Near(reversed.LooseCommonBorrow,0,"Demand order independent");
  var shortage=EarthworkBalance.Calculate(new[]{new EarthworkMaterial{Bank=10,Fill=100}});Near(shortage.LooseCommonBorrow,91/0.9*1.2,"Only shortfall becomes common borrow");soil.Reusable=0;b=EarthworkBalance.Calculate(new[]{soil,demand});Near(b.LooseFromExcavation,0,"Unsuitable excluded");Near(b.UnsuitableLoose,120,"Unsuitable disposal");Near(b.LooseCommonBorrow,80/0.9*1.2,"Unsuitable forces borrow");Reject(()=>EarthworkBalance.Calculate(new[]{new EarthworkMaterial{Shrink=100}}),"Singular shrink rejected");
  var cfg=CalculationStore.Resolve(21,40,275,60,420);var f=FootingTakeoff.Calculate("F1","Test footing",2,1.5,.4,2,.5,75,true,Bars(),0,cfg,20,10,100);Near(f.Concrete,2.4,"Footing concrete");Near(f.Forms,5.6,"Footing forms sides only");Near(f.Excavation,5.46,"Footing working allowance");Near(f.Gravel,.6,"Gravel footprint x 0.10 x quantity");Near(f.Backfill,2.46,"Void subtracts concrete and gravel");Check(f.Steel.Result.Lines[0].PiecesPerBeam==10,"Spacing gives max actual spacing");Near(f.Steel.Result.Lines[0].CutLength,1.85,"X cut follows length");Near(f.Steel.Result.Lines[1].CutLength,1.35,"Y cut follows width");Check(f.Steel.Result.Lines[1].PiecesPerBeam==8,"Manual count");Near(f.Steel.Result.Total,10*1.85*2*1.578+8*1.35*2*.888,"Rebar net and grade");Check(CommercialBars.Allocate(new[]{f.Steel},cfg).All(a=>a.Choice!=null),"Commercial stock chosen");var earthCast=FootingTakeoff.Calculate("F1","Test",2,1.5,.4,1,.5,75,false,Bars(),0,cfg,20,10,100);Near(earthCast.Forms,0,"Earth cast no side forms");var both=Bars();both[0].Count=8;Reject(()=>FootingTakeoff.Calculate("F1","Test",2,1.5,.4,1,.5,75,true,both,0,cfg,20,10,100),"Spacing AND count rejected");Reject(()=>FootingTakeoff.Calculate("F1","Test",2,1.5,.4,1,.49,75,true,Bars(),0,cfg,20,10,100),"Too shallow footing excavation");
  using(var form=new ProgramOfWorksForm()){var grid=Field<DataGridView>(form,"cutFill");grid.Rows.Add("A","Site grading","0+000","0+020","2","4","1","2","100","20","10");var feet=Field<DataGridView>(form,"footings");int n=feet.Rows.Add();var row=feet.Rows[n];row.Cells[0].Value="F1";row.Cells[1].Value="Footing";row.Cells[2].Value="2";row.Cells[3].Value="1.5";row.Cells[4].Value="0.4";row.Cells[5].Value="2";Call(form,"Recalculate");var overall=Field<EarthworkBalance>(form,"earthBalance");Near(overall.Excavation,60+5.46,"Cut and footing included once");Near(overall.Fill,30+2.46,"Global compacted space");Near(overall.LooseCommonBorrow,0,"Global reuse before borrow");var tables=form.WorksExcelTables();var earth=tables.Single(t=>t.Name=="POW Overall Earthworks");Near(Convert.ToDouble(earth.Rows[9,1]),.6*1.05,"Gravel purchase allowance applied once");var main=tables.Single(t=>t.Name==WorksSummaryLayout.Sheet&&t.StartColumn==1);Near(Convert.ToDouble(main.Rows[32,1]),2.4,"Fixed footing concrete B34");Check(tables.Single(t=>t.Name=="POW Rebar").Rows.GetLength(0)>0,"Footing steel in global grade totals");string xml=form.WorksProjectXml();Check(xml.Contains("version=\"11\""),"Project schema updated");using(var opened=new ProgramOfWorksForm()){opened.OpenProjectXml(xml);Near(Field<EarthworkBalance>(opened,"earthBalance").Excavation,overall.Excavation,"Saved project round trip");Check(Field<DataGridView>(opened,"footings").Rows[0].Cells[0].Value.ToString()=="F1","Footing inputs restored");var report=(string)Call(opened,"BuildWorksReport","Program of Works Summary",true);Check(report.Contains("FOOTING WORKS")&&report.Contains("GRAVEL TO BUY"),"Unified backup report");}
   // Overlap errors block exports instead of silently doubling earthwork.
   grid.Rows.Add("A","Overlap","10","30","1","1","0","0","100","20","10");Call(form,"Recalculate");Reject(()=>Call(form,"BuildWorksReport","Earthworks & Gravel",true),"Overlap prevents final report");
  }
  Console.WriteLine("PASS: "+checks+" cut/fill, footing, pooled earthwork, gravel, purchase, report, Excel and project checks.");
 }
}
